#define _GNU_SOURCE
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

int contador = 7;                       /* variable global: vive en el espacio de direcciones */

/* Numero de marco fisico (PFN) de la pagina donde esta p, leido de /proc/self/pagemap.
   Solo lo muestra root: sin privilegios el kernel devuelve 0. */
static uint64_t marco(void *p) {
    int fd = open("/proc/self/pagemap", O_RDONLY);
    uint64_t e = 0;
    pread(fd, &e, sizeof e, ((uintptr_t)p / 4096) * 8);
    close(fd);
    return (e >> 63) ? (e & ((1ULL << 55) - 1)) : 0;
}

static void mostrar(const char *quien) {
    printf("%-42s &contador=%p  valor=%-2d  marco fisico=0x%lx\n",
           quien, (void *)&contador, contador, (unsigned long)marco(&contador));
    fflush(stdout);
}

int main(void) {
    mostrar("padre, antes del fork:");
    pid_t hijo = fork();
    if (hijo == 0) {
        mostrar("hijo, recien nacido:");
        contador = 42;                  /* el hijo escribe */
        mostrar("hijo, despues de escribir 42:");
        _exit(0);
    }
    waitpid(hijo, NULL, 0);
    mostrar("padre, despues de que escribio el hijo:");
    return 0;
}

