#define _GNU_SOURCE
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

static void tamanos(const char *titulo) {
    char l[160];
    FILE *f = fopen("/proc/self/status", "r");
    printf("%s\n", titulo);
    while (fgets(l, sizeof l, f))
        if (!strncmp(l, "VmSize", 6) || !strncmp(l, "VmRSS", 5)) printf("  %s", l);
    fclose(f);
}

int main(void) {
    size_t tib = 1UL << 40;                                   /* 1 TiB */
    tamanos("Al empezar:");

    /* 1) pedir 1 TiB de memoria escribible: el kernel lo rechaza */
    void *a = mmap(NULL, tib, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    printf("1 TiB escribible: %s\n", a == MAP_FAILED ? "rechazado" : "aceptado");

    /* 2) reservar 1 TiB de direcciones sin permiso de uso: lo acepta */
    void *p = mmap(NULL, tib, PROT_NONE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
    printf("1 TiB reservado (PROT_NONE) en %p\n", p);
    tamanos("Con 1 TiB reservado:");

    /* 3) pedir una direccion por encima de los 47 bits (128 TiB) */
    void *pedida = (void *)(1UL << 48);
    void *q = mmap(pedida, 1 << 20, PROT_NONE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    printf("pedi %p y el kernel dio %p\n", pedida, q);
    return 0;
}
